import { test } from 'node:test';
import assert from 'node:assert/strict';

import { dfsOrder, findCycle, kahnOrder, layers } from '../src/topo.js';

/**
 * Deterministic 32-bit PRNG.
 * @param {number} seed Initial state.
 * @returns {() => number} Generator returning floats in [0, 1).
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Enumerates every permutation of a list.
 * @param {string[]} items Items to permute.
 * @returns {string[][]} All permutations.
 */
function permutations(items) {
  if (items.length <= 1) return [items.slice()];
  const out = [];
  for (let i = 0; i < items.length; i += 1) {
    const rest = items.slice(0, i).concat(items.slice(i + 1));
    for (const tail of permutations(rest)) out.push([items[i], ...tail]);
  }
  return out;
}

/**
 * Reports whether an ordering respects every edge.
 * @param {Record<string, string[]>} graph Dependency graph.
 * @param {string[]} order Candidate ordering.
 * @returns {boolean} True when every edge points forward.
 */
function respectsEdges(graph, order) {
  const at = new Map(order.map((node, index) => [node, index]));
  if (at.size !== Object.keys(graph).length) return false;
  for (const [node, targets] of Object.entries(graph)) {
    for (const target of targets) {
      if (!(at.get(node) < at.get(target))) return false;
    }
  }
  return true;
}

/**
 * Builds a random directed acyclic graph.
 * @param {() => number} rnd Generator.
 * @param {number} size Node count.
 * @returns {Record<string, string[]>} Graph with shuffled ids.
 */
function randomDag(rnd, size) {
  const ids = 'kdqbxjznwfmtapr'.split('').slice(0, size);
  for (let i = ids.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rnd() * (i + 1));
    [ids[i], ids[j]] = [ids[j], ids[i]];
  }
  const graph = {};
  for (const id of ids) graph[id] = [];
  for (let i = 0; i < ids.length; i += 1) {
    for (let j = i + 1; j < ids.length; j += 1) {
      if (rnd() < 0.35) graph[ids[i]].push(ids[j]);
    }
  }
  return graph;
}

test('kahnOrder always takes the smallest ready node', () => {
  assert.deepEqual(kahnOrder({}), { ok: true, order: [] });
  assert.deepEqual(kahnOrder({ a: ['b'], b: ['c'], c: [] }), { ok: true, order: ['a', 'b', 'c'] });
  assert.deepEqual(kahnOrder({ c: [], b: ['c'], a: ['b'] }), { ok: true, order: ['a', 'b', 'c'] });
  assert.deepEqual(kahnOrder({ a: ['d'], b: ['d'], c: [], d: [] }), { ok: true, order: ['a', 'b', 'c', 'd'] });
  assert.deepEqual(kahnOrder({ z: ['a'], a: [], m: [] }), { ok: true, order: ['m', 'z', 'a'] });
  assert.deepEqual(
    kahnOrder({ build: ['test', 'lint'], test: ['ship'], lint: ['ship'], ship: [], docs: [] }),
    { ok: true, order: ['build', 'docs', 'lint', 'test', 'ship'] },
  );
  assert.deepEqual(kahnOrder({ a: ['b', 'b', 'b'], b: [] }), { ok: true, order: ['a', 'b'] });
  assert.deepEqual(kahnOrder({ B: ['a'], a: [], b: [] }), { ok: true, order: ['B', 'a', 'b'] });
});

test('dfsOrder reverses depth-first finishing times', () => {
  assert.deepEqual(dfsOrder({ a: ['b'], b: ['c'], c: [] }), { ok: true, order: ['a', 'b', 'c'] });
  assert.deepEqual(dfsOrder({ a: ['d'], b: ['d'], c: [], d: [] }), { ok: true, order: ['c', 'b', 'a', 'd'] });
  assert.deepEqual(
    dfsOrder({ build: ['test', 'lint'], test: ['ship'], lint: ['ship'], ship: [], docs: [] }),
    { ok: true, order: ['docs', 'build', 'test', 'lint', 'ship'] },
  );
  assert.deepEqual(dfsOrder({ a: [], b: [], c: [] }), { ok: true, order: ['c', 'b', 'a'] });
  assert.deepEqual(dfsOrder({ r: ['m', 'q'], m: ['q'], q: [], s: ['r'] }), { ok: true, order: ['s', 'r', 'm', 'q'] });
});

test('layers place every node one level below its deepest predecessor', () => {
  assert.deepEqual(layers({}), { ok: true, layers: [] });
  assert.deepEqual(layers({ a: [] }), { ok: true, layers: [['a']] });
  assert.deepEqual(layers({ a: ['b'], b: ['c'], c: [] }), { ok: true, layers: [['a'], ['b'], ['c']] });
  assert.deepEqual(
    layers({ build: ['test', 'lint'], test: ['ship'], lint: ['ship'], ship: [], docs: [] }),
    { ok: true, layers: [['build', 'docs'], ['lint', 'test'], ['ship']] },
  );
  assert.deepEqual(layers({ a: ['b', 'c'], b: ['c'], c: [] }), { ok: true, layers: [['a'], ['b'], ['c']] });
});

test('findCycle names one cycle and starts it at the smallest member', () => {
  assert.equal(findCycle({}), null);
  assert.equal(findCycle({ a: ['b'], b: [] }), null);
  assert.deepEqual(findCycle({ a: ['a'] }), ['a']);
  assert.deepEqual(findCycle({ a: ['b'], b: ['a'] }), ['a', 'b']);
  assert.deepEqual(findCycle({ a: ['b'], b: ['c'], c: ['b'] }), ['b', 'c']);
  assert.deepEqual(findCycle({ a: ['b'], b: ['a'], x: ['y'], y: ['x'] }), ['a', 'b']);
  assert.deepEqual(findCycle({ A0: ['z'], z: ['m'], m: ['z'] }), ['m', 'z']);
  assert.deepEqual(findCycle({ p: ['q'], q: ['b'], b: ['p'], done: [] }), ['b', 'p', 'q']);
});

test('cyclic graphs report the cycle instead of an order', () => {
  const graph = { a: ['b'], b: ['c'], c: ['b'], d: ['a'] };
  const byKahn = kahnOrder(graph);
  const byDfs = dfsOrder(graph);
  const byLayers = layers(graph);
  assert.equal(byKahn.ok, false);
  assert.equal(byDfs.ok, false);
  assert.equal(byLayers.ok, false);
  assert.equal(byKahn.order, undefined);
  assert.deepEqual(byKahn.cycle, ['b', 'c']);
  assert.deepEqual(byDfs.cycle, ['b', 'c']);
  assert.deepEqual(byLayers.cycle, ['b', 'c']);
  assert.deepEqual(kahnOrder({ a: ['a'], b: [] }).cycle, ['a']);
});

test('malformed graphs raise the specified errors', () => {
  assert.throws(() => kahnOrder(null), { name: 'TypeError', message: 'graph must be an object' });
  assert.throws(() => kahnOrder([['a']]), { name: 'TypeError', message: 'graph must be an object' });
  assert.throws(() => dfsOrder('a->b'), { name: 'TypeError', message: 'graph must be an object' });
  assert.throws(() => kahnOrder({ a: 'b' }), { name: 'TypeError', message: 'edge list for node "a" must be an array' });
  assert.throws(() => layers({ a: [7] }), { name: 'TypeError', message: 'edge list for node "a" must be an array' });
  assert.throws(() => kahnOrder({ a: ['z'] }), { name: 'ReferenceError', message: 'unknown node: "z"' });
  assert.throws(() => findCycle({ a: ['constructor'] }), { name: 'ReferenceError', message: 'unknown node: "constructor"' });
  assert.throws(() => dfsOrder({ a: ['toString'] }), { name: 'ReferenceError', message: 'unknown node: "toString"' });
  assert.deepEqual(kahnOrder({ constructor: ['toString'], toString: [] }), { ok: true, order: ['constructor', 'toString'] });
});

test('kahnOrder equals the lexicographically smallest valid order on random graphs', () => {
  const rnd = mulberry32(20260907);
  for (let round = 0; round < 40; round += 1) {
    const graph = randomDag(rnd, 5 + (round % 3));
    const ids = Object.keys(graph).sort();
    let best = null;
    for (const candidate of permutations(ids)) {
      if (!respectsEdges(graph, candidate)) continue;
      if (best === null || candidate.join('^@') < best.join('^@')) best = candidate;
    }
    const got = kahnOrder(graph);
    assert.equal(got.ok, true, `round ${round}`);
    assert.deepEqual(got.order, best, `round ${round} ${JSON.stringify(graph)}`);
  }
});

test('both orderings and the layering stay consistent on larger random graphs', () => {
  const rnd = mulberry32(0x5eed);
  for (let round = 0; round < 60; round += 1) {
    const graph = randomDag(rnd, 8 + (round % 8));
    const byKahn = kahnOrder(graph);
    const byDfs = dfsOrder(graph);
    const byLayers = layers(graph);
    assert.equal(findCycle(graph), null, `round ${round}`);
    assert.ok(respectsEdges(graph, byKahn.order), `kahn round ${round}`);
    assert.ok(respectsEdges(graph, byDfs.order), `dfs round ${round}`);
    const level = new Map();
    byLayers.layers.forEach((group, depth) => {
      assert.deepEqual(group, [...group].sort(), `layer ${depth} sorted round ${round}`);
      for (const node of group) level.set(node, depth);
    });
    assert.equal(level.size, Object.keys(graph).length, `layer coverage round ${round}`);
    for (const [node, targets] of Object.entries(graph)) {
      for (const target of targets) {
        assert.ok(level.get(target) > level.get(node), `edge ${node}->${target} round ${round}`);
      }
    }
    for (const [node, depth] of level) {
      if (depth === 0) continue;
      const predecessors = Object.entries(graph).filter(([, targets]) => targets.includes(node));
      assert.ok(
        predecessors.some(([source]) => level.get(source) === depth - 1),
        `node ${node} at depth ${depth} round ${round}`,
      );
    }
  }
});

test('reported cycles are real cycles of the graph', () => {
  const rnd = mulberry32(0xbadc0de);
  for (let round = 0; round < 60; round += 1) {
    const graph = randomDag(rnd, 6 + (round % 6));
    const ids = Object.keys(graph);
    const start = ids[Math.floor(rnd() * ids.length)];
    const seen = new Set();
    const queue = [...graph[start]];
    while (queue.length > 0) {
      const node = queue.pop();
      if (seen.has(node)) continue;
      seen.add(node);
      queue.push(...graph[node]);
    }
    const reachable = [...seen].filter((node) => node !== start);
    const source = reachable.length > 0 ? reachable[Math.floor(rnd() * reachable.length)] : start;
    if (!graph[source].includes(start)) graph[source].push(start);
    const cycle = findCycle(graph);
    assert.ok(Array.isArray(cycle) && cycle.length > 0, `round ${round} ${JSON.stringify(graph)}`);
    assert.equal(new Set(cycle).size, cycle.length, `round ${round} distinct`);
    assert.equal(cycle[0], [...cycle].sort()[0], `round ${round} starts at smallest`);
    for (let i = 0; i < cycle.length; i += 1) {
      const next = cycle[(i + 1) % cycle.length];
      assert.ok(graph[cycle[i]].includes(next), `round ${round} edge ${cycle[i]}->${next}`);
    }
    assert.equal(kahnOrder(graph).ok, false, `round ${round} kahn`);
    assert.equal(dfsOrder(graph).ok, false, `round ${round} dfs`);
  }
});

