 * before `b`.
 */

/**
 * Reports whether a value is a non-null, non-array object.
 * @param {unknown} value Candidate graph.
 * @returns {boolean} True when the value could hold a graph.
 */
function isGraphLike(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Validates a graph, raising the specified errors on malformed input.
 * @param {unknown} graph Candidate graph.
 * @returns {string[]} The graph's own node ids.
 */
function validateGraph(graph) {
  if (!isGraphLike(graph)) {
    throw new TypeError('graph must be an object');
  }
  const nodes = Object.keys(graph);
  const nodeSet = new Set(nodes);
  for (const node of nodes) {
    const edges = graph[node];
    if (!Array.isArray(edges) || !edges.every((edge) => typeof edge === 'string')) {
      throw new TypeError(`edge list for node "${node}" must be an array`);
    }
  }
  for (const node of nodes) {
    for (const target of graph[node]) {
      if (!nodeSet.has(target)) {
        throw new ReferenceError(`unknown node: "${target}"`);
      }
    }
  }
  return nodes;
}

/**
 * Finds one cycle, exploring nodes and successors in ascending id order.
 * @param {unknown} graph Dependency graph.
 * @returns {string[] | null} Cycle in edge order starting at its smallest id, or null.
 */
export function findCycle(graph) {
  const nodes = validateGraph(graph).slice().sort();
  const state = new Map(nodes.map((node) => [node, 0])); // 0 = white, 1 = gray, 2 = black
  const path = [];
  let found = null;

  function visit(node) {
    state.set(node, 1);
    path.push(node);
    const successors = [...new Set(graph[node])].sort();
    for (const successor of successors) {
      if (found) return;
      const status = state.get(successor);
      if (status === 1) {
        const startIndex = path.indexOf(successor);
        let cycle = path.slice(startIndex);
        const smallest = [...cycle].sort()[0];
        const rotateAt = cycle.indexOf(smallest);
        cycle = cycle.slice(rotateAt).concat(cycle.slice(0, rotateAt));
        found = cycle;
        return;
      }
      if (status === 0) {
        visit(successor);
        if (found) return;
      }
    }
    path.pop();
    state.set(node, 2);
  }

  for (const node of nodes) {
    if (found) break;
    if (state.get(node) === 0) visit(node);
  }

  return found;
}

/**
 * Orders the graph with Kahn's algorithm, always taking the smallest ready id.
 * @param {unknown} graph Dependency graph.
 * @returns {{ok: true, order: string[]} | {ok: false, cycle: string[]}} Order or cycle.
 */
export function kahnOrder(graph) {
  validateGraph(graph);
  const cycle = findCycle(graph);
  if (cycle) return { ok: false, cycle };

  const nodes = Object.keys(graph).sort();
  const successors = new Map(nodes.map((node) => [node, new Set(graph[node])]));
  const indegree = new Map(nodes.map((node) => [node, 0]));
  for (const node of nodes) {
    for (const target of successors.get(node)) {
      indegree.set(target, indegree.get(target) + 1);
    }
  }

  const available = new Set(nodes.filter((node) => indegree.get(node) === 0));
  const order = [];
  while (available.size > 0) {
    const next = [...available].sort()[0];
    available.delete(next);
    order.push(next);
    for (const target of successors.get(next)) {
      indegree.set(target, indegree.get(target) - 1);
      if (indegree.get(target) === 0) available.add(target);
    }
  }

  return { ok: true, order };
}

/**
 * Orders the graph by reversed depth-first finishing times.
 * @param {unknown} graph Dependency graph.
 * @returns {{ok: true, order: string[]} | {ok: false, cycle: string[]}} Order or cycle.
 */
export function dfsOrder(graph) {
  validateGraph(graph);
  const cycle = findCycle(graph);
  if (cycle) return { ok: false, cycle };

  const nodes = Object.keys(graph).sort();
  const visited = new Set();
  const finished = [];

  function visit(node) {
    visited.add(node);
    const successors = [...new Set(graph[node])].sort();
    for (const successor of successors) {
      if (!visited.has(successor)) visit(successor);
    }
    finished.push(node);
  }

  for (const node of nodes) {
    if (!visited.has(node)) visit(node);
  }

  return { ok: true, order: finished.reverse() };
}

/**
 * Groups nodes into dependency levels: a node sits one level below its deepest
 * predecessor, and each level is listed in ascending id order.
 * @param {unknown} graph Dependency graph.
 * @returns {{ok: true, layers: string[][]} | {ok: false, cycle: string[]}} Levels or cycle.
 */
export function layers(graph) {
  validateGraph(graph);
  const cycle = findCycle(graph);
  if (cycle) return { ok: false, cycle };

  const nodes = Object.keys(graph).sort();
  const predecessors = new Map(nodes.map((node) => [node, new Set()]));
  for (const node of nodes) {
    for (const target of new Set(graph[node])) {
      predecessors.get(target).add(node);
    }
  }

  const topo = kahnOrder(graph).order;
  const level = new Map();
  for (const node of topo) {
    const preds = predecessors.get(node);
    if (preds.size === 0) {
      level.set(node, 0);
    } else {
      let depth = 0;
      for (const pred of preds) depth = Math.max(depth, level.get(pred) + 1);
      level.set(node, depth);
    }
  }

  let maxLevel = -1;
  for (const depth of level.values()) maxLevel = Math.max(maxLevel, depth);

  const result = [];
  for (let i = 0; i <= maxLevel; i += 1) result.push([]);
  for (const node of nodes) result[level.get(node)].push(node);

  return { ok: true, layers: result };
}
"}

